// Generated by Viscosity: "marked" stored as a struct of arrays (fields v).
class __Vsc_marked {
  constructor(cap = 16) { this.length = 0; this.cap = cap; this.v = new Float64Array(cap); }
  static of(...v) { const c = new __Vsc_marked(Math.max(16, v.length / 1)); for (let i = 0; i < v.length; i += 1) c.push(v[i + 0]); return c; }
  push(v0) { const n = this.length; if (n === this.cap) this.grow(); this.v[n] = v0; return (this.length = n + 1); }
  grow() { const cap = (this.cap *= 2); let t; t = new Float64Array(cap); t.set(this.v); this.v = t; }
}
// viscosity(opt-in): marked=soa, unmarked=aos
// @viscosity soa
const marked = new __Vsc_marked();
const unmarked = [];
for (let i = 0; i < 300; i++) {
  marked.push(i);
  unmarked.push({ v: i });
}
let s = 0;
for (let i = 0; i < marked.length; i++) s += marked.v[i] + unmarked[i].v;
console.log(s);
